// JSON logger that stamps every line with the active trace ID. Generated by `eos scaffold otel-node`.
// One JSON object per line on stdout; the platform ships it. Log IDs, not values: fields whose name looks
// secret are redacted as a seatbelt (the eos-js-log-secret Semgrep rule catches the obvious cases).
// Usage: import { log } from "@/lib/logger"; log.info("payment created", { paymentId });
import { trace } from "@opentelemetry/api";

type Level = "debug" | "info" | "warn" | "error";
const ORDER: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };
const MIN = ORDER[(process.env.LOG_LEVEL?.toLowerCase() as Level) ?? "info"] ?? ORDER.info;
const SECRET = /password|passwd|secret|token|api_?key|authorization|cookie|card_?number|cvv/i;

export function currentTraceId(): string | undefined {
  const ctx = trace.getActiveSpan()?.spanContext();
  return ctx && ctx.traceId !== "00000000000000000000000000000000" ? ctx.traceId : undefined;
}

function emit(level: Level, message: string, fields: Record<string, unknown> = {}): void {
  if (ORDER[level] < MIN) return;
  const ctx = trace.getActiveSpan()?.spanContext();
  const line: Record<string, unknown> = { time: new Date().toISOString(), level, message };
  if (ctx && ctx.traceId !== "00000000000000000000000000000000") {
    line.trace_id = ctx.traceId;
    line.span_id = ctx.spanId;
  }
  for (const [k, v] of Object.entries(fields)) {
    line[k] = SECRET.test(k) ? "[REDACTED]" : v instanceof Error ? { name: v.name, message: v.message, stack: v.stack } : v;
  }
  (level === "error" || level === "warn" ? process.stderr : process.stdout).write(JSON.stringify(line) + "\n");
}

export const log = {
  debug: (m: string, f?: Record<string, unknown>) => emit("debug", m, f),
  info: (m: string, f?: Record<string, unknown>) => emit("info", m, f),
  warn: (m: string, f?: Record<string, unknown>) => emit("warn", m, f),
  error: (m: string, f?: Record<string, unknown>) => emit("error", m, f),
};
